from envfile import parse_env


def test_skips_comment_lines():
    assert parse_env("# database\nA=1") == {"A": "1"}


def test_strips_double_quotes():
    assert parse_env('A="x y"') == {"A": "x y"}


def test_strips_single_quotes():
    assert parse_env("A='x'") == {"A": "x"}


def test_keeps_extra_equals():
    assert parse_env('URL="a=b"') == {"URL": "a=b"}


def test_blank_and_whitespace_lines():
    assert parse_env("\n  \nA=1") == {"A": "1"}

